const ingaDays=[{"number":1,"title":"Zlatni list na prozoru","ribbon":"DAN 1 · VRATA AKADEMIJE","story":[{"heading":"Avantura 1 · Tajna Starog hrasta","html":"<section class='story-scene single-story'><h3>Zlatni list na prozoru</h3><p>Jutro je počelo neobično. Na Inginom prozoru ležao je zlatni list koji je u zraku nacrtao stazu prema Velikoj šumi. Na starim vratima Inga je primijetila četiri zlatna početna slova. Složila ih je i dobila riječ VJERA. Vrata su se otvorila, a iz tame se začuo glas Mudre sove. Inga je zakoračila unutra, ne znajući da je upravo započela potragu za sedam ključeva znanja.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koju je riječ Inga dobila od zlatnih početnih slova?","options":["SNAGA","VJERA","BRZINA"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · Let’s Start!</small><h3>HELLO</h3><p class='english-sentence'>Hello! My name is Inga.</p><button class='english-speak' data-english='Hello! My name is Inga.'>🔊 Poslušaj</button><p>Pozdravi Mudru sovu i reci svoje ime.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Na Inginom prozoru ležao je list boje meda, iako u dvorištu nije bilo nijednog takvog stabla. Po njegovim žilicama svjetlucala su sitna slova, kao da ih je netko napisao mjesečinom.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"U četiri košarice nalazi se po 6 zlatnih listova. Inga je 5 listova stavila u bilježnicu. Koliko je listova ostalo u košaricama? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[19]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koju je riječ Inga dobila od zlatnih početnih slova? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":2,"title":"Put prema Velikoj šumi","ribbon":"DAN 2 · STAZA SVIJETLA","story":[{"heading":"Avantura 2 · Svjetiljka pažnje","html":"<section class='story-scene single-story'><h3>Put prema Velikoj šumi</h3><p>Mudra sova predala je Ingi plavu svjetiljku koja svijetli samo kada pažljivo promatra. Na prvom raskrižju Inga je požurila i svjetiljka se ugasila. Vratila se, pročitala znakove polako i uočila pravi put. Shvatila je da pažnja znači zastati, usporediti tragove i tek tada odlučiti. Na kraju staze čekao ju je prvi sjajni znak Akademije.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Zašto se svjetiljka ugasila na prvom raskrižju?","options":["Jer je Inga požurila i nije pogledala znakove.","Jer je nestalo baterije.","Jer je svanulo."],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Family</small><h3>FAMILY</h3><p class='english-sentence'>This is my family.</p><button class='english-speak' data-english='This is my family.'>🔊 Poslušaj</button><p>Imenuj članove svoje obitelji na engleskom.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Mudra sova predala je Ingi plavu svjetiljku koja svijetli samo kada pažljivo promatra. Na prvom raskrižju Inga je požurila i svjetiljka se ugasila.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Veliko početno slovo","text":"U prepisanim rečenicama zaokruži riječi koje počinju velikim slovom. Zatim napiši jednu rečenicu u kojoj ćeš pravilno upotrijebiti ime Inga i naziv Velika šuma.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Na 5 stupova postavljene su po 3 lampice, a zatim su dodane još 4 lampice uz ulaz. Koliko lampica sada svijetli? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[19]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Zašto se svjetiljka ugasila na prvom raskrižju? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":3,"title":"Susret s Milom","ribbon":"DAN 3 · VJEVERIČINA KUĆICA","story":[{"heading":"Avantura 3 · Mila i izgubljena karta","html":"<section class='story-scene single-story'><h3>Susret s Milom</h3><p>U Akademiju je utrčala vjeverica Mila. Njezina karta Velike šume nestala je sa stola. Inga je pronašla lagane tragove papira, otvoren prozor i pero na grani. Nije optužila nikoga, nego je povezala tragove. Jak vjetar odnio je kartu do starog bora. Mila se nasmiješila, a karta je otkrila novu stazu koja vodi prema rijeci.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je zapravo odnijelo kartu s Milina stola?","options":["Bruno jež","Snažan vjetar","Mudra sova"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Family</small><h3>SISTER</h3><p class='english-sentence'>This is my sister.</p><button class='english-speak' data-english='This is my sister.'>🔊 Poslušaj</button><p>Odaberi: mother, father, brother ili sister.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Mila je u Akademiju utrčala toliko brzo da su joj lješnjaci ispali iz torbice. Karta Velike šume, jedina na kojoj su bili označeni skriveni prolazi, nestala je tijekom noći.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Mila ima 6 vrećica s po 4 lješnjaka. Sve ih ravnomjerno dijeli na 3 police. Koliko lješnjaka stavlja na svaku policu? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[8]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je zapravo odnijelo kartu s Milina stola? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":4,"title":"Dabrov most","ribbon":"DAN 4 · RIJEKA ZNANJA","story":[{"heading":"Avantura 4 · Dabrov most","html":"<section class='story-scene single-story'><h3>Dabrov most</h3><p>Kod rijeke je dabar Bor pokušavao popraviti most. Imao je nekoliko dasaka, ali nije znao koliko još nedostaje. Inga je prebrojila prazna mjesta, usporedila ih s pripremljenim daskama i izračunala razliku. Most je ponovno postao siguran. Dok su prelazili, ispod posljednje daske pronašli su znak drugog ključa.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga odredila koliko još dasaka treba?","options":["Nasumično je odabrala broj.","Pomnožila je broj dijelova i dasaka, pa oduzela već postavljene.","Pitala je vjevericu."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My House</small><h3>HOUSE</h3><p class='english-sentence'>This is my house.</p><button class='english-speak' data-english='This is my house.'>🔊 Poslušaj</button><p>Pokaži i imenuj: door, window, roof.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Dabrić Niko gradio je most preko brze Rijeke znanja. Imao je šest jednakih dijelova, a za svaki su mu trebale četiri daske.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Za 7 dijelova mosta trebaju po 3 daske. Dabrić već ima 9 dasaka. Koliko mu još dasaka nedostaje? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[12]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga odredila koliko još dasaka treba? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":5,"title":"Vrt zaboravljenih riječi","ribbon":"DAN 5 · ČAROBNI VRT","story":[{"heading":"Avantura 5 · Vrt zaboravljenih riječi","html":"<section class='story-scene single-story'><h3>Vrt zaboravljenih riječi</h3><p>S druge strane mosta nalazio se vrt u kojem su biljke izgubile svoja imena. Dvije su izgledale gotovo jednako, ali Inga je pažljivo usporedila oblik listova, boju cvjetova i miris. Sitni detalji pomogli su joj razlikovati biljke. Kada je pravilno pročitala njihove nazive, vrt je ponovno procvjetao, a među laticama se pojavila poruka.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je Ingi pomoglo razlikovati dvije slične biljke?","options":["Oblik listova","Visina ograde","Broj oblaka"],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My House</small><h3>KITCHEN</h3><p class='english-sentence'>The kitchen is in my house.</p><button class='english-speak' data-english='The kitchen is in my house.'>🔊 Poslušaj</button><p>Pronađi prostoriju: bedroom, kitchen ili bathroom.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „U čarobnom vrtu sve su pločice s imenima biljaka izblijedjele. Ruže su tvrdile da su tulipani, ljubičice su se skrivale među tratinčicama, a vrtlar Krtko nije znao kako ih ponovno razvrstati.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"U 8 redova posađeno je po 5 cvjetova. Vrtlar je uklonio 6 uvelih cvjetova. Koliko je zdravih cvjetova ostalo? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[34]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je Ingi pomoglo razlikovati dvije slične biljke? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":6,"title":"Sat koji je izgubio minute","ribbon":"DAN 6 · TORANJ VREMENA","story":[{"heading":"Avantura 6 · Sat koji je izgubio minute","html":"<section class='story-scene single-story'><h3>Sat koji je izgubio minute</h3><p>Poruka je Ingu odvela do tornja sa satom koji je preskakao minute. Umjesto da nasumce okreće kazaljke, zapisala je niz vremena i pronašla pravilnost u kvaru. Svaki se četvrti korak ponavljao. Kada je postavila kazaljke na pravo mjesto, sat je zazvonio i otvorio tajni prolaz prema Zvjezdanoj knjižnici.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koji je niz Inga zapisala dok je promatrala kvar?","options":["10, 15, 20, 25","1, 3, 8, 20","50, 40, 25, 7"],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Birthday</small><h3>BIRTHDAY</h3><p class='english-sentence'>Happy birthday!</p><button class='english-speak' data-english='Happy birthday!'>🔊 Poslušaj</button><p>Izgovori brojeve od one do ten.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „U Tornju vremena veliki je sat prestao otkucavati. Kazaljke su se kretale, ali su preskakale svakih pet minuta.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Trideset zupčanika raspoređeno je u 5 jednakih skupina. Dvije skupine već su očišćene. Koliko zupčanika još treba očistiti? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[18]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koji je niz Inga zapisala dok je promatrala kvar? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":7,"title":"Zvjezdana knjižnica","ribbon":"DAN 7 · KNJIŽNICA NEBA","story":[{"heading":"Avantura 7 · Zvjezdana knjižnica","html":"<section class='story-scene single-story'><h3>Zvjezdana knjižnica</h3><p>U knjižnici su knjige svijetlile poput zvijezda. Na jednoj je stranici bila pjesma čija su prva slova redaka skrivala poruku. Inga ih je pročitala redom i otkrila smjer kojim treba krenuti. Mudra sova joj je objasnila da tekst ponekad govori više nego što se vidi na prvi pogled. Iza police otvorila su se vrata prema Srebrnom potoku.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga pronašla skrivenu poruku u pjesmi?","options":["Prebrojila je stranice.","Pročitala je prva slova stihova.","Zatvorila je knjigu."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Birthday</small><h3>CAKE</h3><p class='english-sentence'>This is my birthday cake.</p><button class='english-speak' data-english='This is my birthday cake.'>🔊 Poslušaj</button><p>Reci koliko svjećica vidiš.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Na vrhu brda nalazila se knjižnica bez polica. Knjige su lebdjele poput zvijezda, a do svake se moglo doći samo ako čitatelj postavi dobro pitanje.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Na 6 polica nalazi se po 7 knjiga. Učenici su posudili 8 knjiga. Koliko je knjiga ostalo? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[34]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga pronašla skrivenu poruku u pjesmi? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":8,"title":"Šapat Srebrnog potoka","ribbon":"DAN 8 · SREBRNI POTOK","story":[{"heading":"Avantura 8 · Šapat Srebrnog potoka","html":"<section class='story-scene single-story'><h3>Šapat Srebrnog potoka</h3><p>Potok nije govorio glasom, nego valovima. Inga je mirno promatrala kako se slova pojavljuju na površini. Kada ih je spojila, pročitala je riječ STRPLJENJE. Voda se razmaknula i pokazala kamenčiće koji vode preko potoka. Na posljednjem kamenu čekala ju je Milina nova zagonetka.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koju je riječ potok ispisao na površini?","options":["SLUŠAJ","TRČI","SKAČI"],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Animals</small><h3>ANIMAL</h3><p class='english-sentence'>I like animals.</p><button class='english-speak' data-english='I like animals.'>🔊 Poslušaj</button><p>Imenuj tri životinje na engleskom.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Srebrni potok obično je pjevao, ali toga je jutra šaputao jedva čujno. Riječi su dolazile u kratkim dijelovima: ‘tri kamena… dva kruga… posljednji trag’.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Potok je pokazao 4 skupine s po 6 srebrnih kamenčića. Inga je 9 kamenčića vratila u vodu. Koliko ih je ostalo na obali? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[15]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koju je riječ potok ispisao na površini? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":9,"title":"Vjeveričina zagonetka","ribbon":"DAN 9 · STABLO ZAGONETKI","story":[{"heading":"Avantura 9 · Vjeveričina zagonetka","html":"<section class='story-scene single-story'><h3>Vjeveričina zagonetka</h3><p>Mila je donijela košaru žireva i zamolila Ingu da ih pravedno podijeli među tri prijatelja. Inga ih je rasporedila u jednake skupine i provjerila da nitko nije dobio više. Kada je izgovorila rezultat, jedan je žir zasjao jače od ostalih i pretvorio se u putokaz prema Mostu hrabrosti.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koliko je žireva dobio svaki od tri prijatelja?","options":["6","8","24"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Animals</small><h3>CAT</h3><p class='english-sentence'>The cat is small.</p><button class='english-speak' data-english='The cat is small.'>🔊 Poslušaj</button><p>Odaberi pridjev: big, small, fast ili slow.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Mila je pronašla stablo s sedam malih vrata. Na svakima je bio matematički znak, a iza samo jednih nalazio se trag.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"U 6 vrećica nalaze se po 4 žira. Žirevi se ravnomjerno dijele među 3 prijatelja. Koliko žireva dobiva svaki prijatelj? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[8]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koliko je žireva dobio svaki od tri prijatelja? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":10,"title":"Most hrabrosti","ribbon":"DAN 10 · KLISURA ODLUKE","story":[{"heading":"Avantura 10 · Most hrabrosti","html":"<section class='story-scene single-story'><h3>Most hrabrosti</h3><p>Na mostu je svaka pogrešna pretpostavka pretvarala dasku u maglu. Inga nije odmah znala odgovor, ali nije odustala. Ponovno je pročitala pitanje, izdvojila važne podatke i pokušala drugim putem. Most se učvrstio. Mudra sova joj je rekla da hrabrost nije znati sve, nego pokušati ponovno kada nije lako.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je Inga učinila kada nije odmah znala odgovor?","options":["Odustala je.","Podijelila je problem na manje korake.","Nasumično je pogodila."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Toys</small><h3>TOY</h3><p class='english-sentence'>This is my favourite toy.</p><button class='english-speak' data-english='This is my favourite toy.'>🔊 Poslušaj</button><p>Opiši igračku bojom i veličinom.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Ispred Inge protezao se most od svjetlosti. Svaka daska pojavila bi se tek kada izgovori nešto što zna, a nestala bi ako samo nagađa.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Graditelji imaju 5 košara s po 6 užadi. Potrošili su 8 užadi. Koliko užadi im je ostalo? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[22]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je Inga učinila kada nije odmah znala odgovor? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":11,"title":"Špijun izgubljenih riječi","ribbon":"DAN 11 · GRAD TIHIH NATPISA","story":[{"heading":"Avantura 11 · Špijun izgubljenih riječi","html":"<section class='story-scene single-story'><h3>Špijun izgubljenih riječi</h3><p>U malom šumskom gradu iz rečenica su nestali glagoli. Bez njih nitko nije znao što se događa. Inga je pratila prazna mjesta, prepoznavala radnje i vraćala odgovarajuće riječi. Grad je ponovno oživio: ptice su pjevale, voda je tekla, a djeca su se igrala. Posljednji glagol pokazao je put prema Jezeru zrcala.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koja je vrsta riječi nestala iz gradskih rečenica?","options":["Imenice","Glagoli","Brojevi"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Toys</small><h3>BALL</h3><p class='english-sentence'>I have got a ball.</p><button class='english-speak' data-english='I have got a ball.'>🔊 Poslušaj</button><p>Vježbaj: I have got… / I haven’t got…</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „U Gradu tihih natpisa iz rečenica su nestali svi glagoli. Na pekarnici je pisalo ‘Pekar kruh’, na stanici ‘Autobus u sedam’, a na vratima škole ‘Učenici knjige’.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"U tiskari su 4 ladice s po 9 kartica. Patuljak je 12 kartica već posložio. Koliko kartica još treba posložiti? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[24]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koja je vrsta riječi nestala iz gradskih rečenica? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":12,"title":"Jezero zrcala","ribbon":"DAN 12 · JEZERO ODGOVORA","story":[{"heading":"Avantura 12 · Jezero zrcala","html":"<section class='story-scene single-story'><h3>Jezero zrcala</h3><p>Jezero je Ingi pokazivalo samo ono čega se bojala. Umjesto da se okrene, prisjetila se svega što je već naučila. Ključ nije bio na dnu vode, nego u odrazu starog drveta iza nje. Okrenula se i pronašla ga u šupljini. Jezero se smirilo, a na obali se pojavio Čuvar Zlatnih žireva.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Gdje je Inga pronašla ključ?","options":["U podstavi Miline torbice","U ptičjem gnijezdu","Na dnu jezera"],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Holidays</small><h3>HOLIDAY</h3><p class='english-sentence'>I am on holiday.</p><button class='english-speak' data-english='I am on holiday.'>🔊 Poslušaj</button><p>Reci: sun, sea, sand, boat.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Jezero zrcala pokazivalo je tri verzije istog događaja. U prvom odrazu Mila je ispustila ključ, u drugom ga je odnijela ptica, a u trećem je ključ cijelo vrijeme bio u džepu.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Na jezeru plovi 7 čamaca s po 4 putnika. Na prvoj postaji izašlo je 6 putnika. Koliko je putnika ostalo u čamcima? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[22]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Gdje je Inga pronašla ključ? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":13,"title":"Čuvar Zlatnih žireva","ribbon":"DAN 13 · RIZNICA ZNANJA","story":[{"heading":"Avantura 13 · Čuvar Zlatnih žireva","html":"<section class='story-scene single-story'><h3>Čuvar Zlatnih žireva</h3><p>Čuvar je otvorio riznicu punu sjajnih žireva, medalja i dragulja. Ipak, rekao je da najveće blago nije predmet. Inga je pogledala tragove svojih pokušaja, ispravljenih pogrešaka i pomoći prijateljima. Shvatila je da je najvažnije blago znanje koje je stekla i hrabrost da nastavi učiti.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je bilo najvažnije blago u riznici?","options":["Novac","Priče, izumi i pitanja učenika","Zlatne krune"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Holidays</small><h3>BOAT</h3><p class='english-sentence'>The boat is on the sea.</p><button class='english-speak' data-english='The boat is on the sea.'>🔊 Poslušaj</button><p>Složi rečenicu od četiri riječi.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Čuvar Zlatnih žireva, veliki jazavac Argo, nije dopuštao ulazak u riznicu bez dokaza da posjetitelj razumije vrijednost znanja. Nije tražio lozinku, nego tri objašnjenja: kako učimo iz pogreške, zašto provjeravamo odgovor i kako pomažemo drugome.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Na 8 polica nalazi se po 5 žireva. Dvanaest je podijeljeno učenicima, a ostatak je raspoređen u 4 kutije. Koliko žireva dolazi u svaku kutiju? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[7]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je bilo najvažnije blago u riznici? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":14,"title":"Prvi ključ Akademije","ribbon":"DAN 14 · DVORANA KLJUČEVA","story":[{"heading":"Avantura 14 · Prvi ključ Akademije","html":"<section class='story-scene single-story'><h3>Prvi ključ Akademije</h3><p>U Dvorani ključeva Inga je rasporedila sve simbole koje je prikupila. Četiri kruga na vratima zasjala su, ali sredina je ostala prazna. Tada je postavila pitanje: „Što mogu pokušati sljedeće?” U sredini se pojavio zlatni ključ. Vrata su se otvorila prema novim područjima Velike šume. Prva velika pustolovina završila je, ali nova je upravo počinjala.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koje je pitanje otvorilo posljednji dio vrata?","options":["Tko je najbrži?","Što mogu pokušati sljedeće?","Gdje je moje blago?"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Magazine Review</small><h3>I CAN</h3><p class='english-sentence'>I can read, count and learn.</p><button class='english-speak' data-english='I can read, count and learn.'>🔊 Poslušaj</button><p>Ponovi riječi iz svih šest modula.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „U Dvorani ključeva Inga je rasporedila sve predmete koje je prikupila: kompas, svjetiljku, kartu, čavao, sjemenke, zvijezdu, kapljicu, drvene oblike, značku, pero, zrcalo i poruke prijatelja. Svaki je predmet predstavljao jednu vještinu.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Inga je prikupila 7 skupina s po 4 znaka. Šest je znakova već upotrijebila na vratima. Koliko joj je znakova ostalo? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[22]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koje je pitanje otvorilo posljednji dio vrata? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":15,"title":"Vrata od mjesečine","ribbon":"DAN 15 · DRUGI KRUG AKADEMIJE","story":[{"heading":"Avantura 15 · Vrata od mjesečine","html":"<section class='story-scene single-story'><h3>Vrata od mjesečine</h3><p>Nakon prvih četrnaest pustolovina Inga se vratila pred Stari hrast. Na kori su se pojavila vrata od mjesečine, ali nisu imala kvaku. Mudra sova objasnila je da ih može otvoriti samo onaj tko razlikuje ono što vidi od onoga što pretpostavlja. Inga je pažljivo promotrila četiri znaka, pronašla onaj koji se ponavljao i vrata su se tiho otvorila. Iza njih je počinjao drugi krug Akademije.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je Inga morala razlikovati kako bi otvorila vrata?","options":["Ono što vidi od onoga što pretpostavlja.","Dan od noći.","Drvo od kamena."],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 15</small><h3>DOOR</h3><p class='english-sentence'>The door is open.</p><button class='english-speak' data-english='The door is open.'>🔊 Poslušaj</button><p>Vrata su otvorena.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Nakon prvih četrnaest pustolovina Inga se vratila pred Stari hrast Na kori su se pojavila vrata od mjesečine, ali nisu imala kvaku.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Veliko početno slovo","text":"U prepisanim rečenicama pronađi i podcrtaj vlastita imena. Zatim napiši dva vlastita imena i dvije opće imenice.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Na vratima su bila 4 reda s po 6 znakova. Pet znakova nije svijetlilo. Koliko je znakova svijetlilo? Napiši račun u dva koraka i odgovor punom rečenicom.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je Inga morala razlikovati kako bi otvorila vrata? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":16,"title":"Šapat kamenih slova","ribbon":"DAN 16 · DVORANA RIJEČI","story":[{"heading":"Avantura 16 · Šapat kamenih slova","html":"<section class='story-scene single-story'><h3>Šapat kamenih slova</h3><p>U dvorani iza vrata lebdjela su kamena slova. Svako se pomaknulo tek kada bi Inga izgovorila riječ jasno i polako. Tri su se slova stalno gurala na pogrešna mjesta. Inga ih nije premještala nasumce, nego je pročitala svaku riječ, poslušala kako zvuči i složila rečenicu: Znanje raste kada ga dijelimo. Na zidu se pojavio trag prema knjižnici.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga pravilno složila kamena slova?","options":["Nasumično ih je premještala.","Pročitala je svaku riječ i slušala kako zvuči.","Zamolila je vjetar."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 16</small><h3>WORDS</h3><p class='english-sentence'>Words make a sentence.</p><button class='english-speak' data-english='Words make a sentence.'>🔊 Poslušaj</button><p>Riječi tvore rečenicu.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „U dvorani iza vrata lebdjela su kamena slova Svako se pomaknulo tek kada bi Inga izgovorila riječ jasno i polako.”","paper":true},{"skill":"Hrvatski jezik","title":"2. ije / je","text":"U prepisanim rečenicama pronađi riječi u kojima čuješ ije ili je. Napiši još po dvije riječi s ije i s je.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Na 7 polica bilo je po 5 kamenih slova. Inga je upotrijebila 8 slova. Koliko je slova ostalo? Prvo izračunaj ukupan broj, zatim oduzmi upotrijebljena slova.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga pravilno složila kamena slova? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":17,"title":"Knjižnica bez naslova","ribbon":"DAN 17 · TAJNA POLICA","story":[{"heading":"Avantura 17 · Knjižnica bez naslova","html":"<section class='story-scene single-story'><h3>Knjižnica bez naslova</h3><p>U zvjezdanoj knjižnici sve su knjige izgubile naslove. Čuvarica knjižnice pokazala je Ingi tri kratka opisa. Inga je u svakome pronašla najvažniju riječ i prema njoj vratila knjigu na pravu policu. Posljednja knjiga zvala se Put hrabrog čitatelja. Kad ju je otvorila, između stranica je pronašla srebrnu oznaku trećeg ključa.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga odredila na koju policu pripada svaka knjiga?","options":["Prema boji korica.","Prema najvažnijoj riječi u opisu.","Prema broju stranica."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 17</small><h3>BOOK</h3><p class='english-sentence'>This book has a title.</p><button class='english-speak' data-english='This book has a title.'>🔊 Poslušaj</button><p>Ova knjiga ima naslov.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „U zvjezdanoj knjižnici sve su knjige izgubile naslove Čuvarica knjižnice pokazala je Ingi tri kratka opisa.”","paper":true},{"skill":"Hrvatski jezik","title":"2. č / ć","text":"Prepiši riječi čuvarica, čitatelj i ključ. Zaokruži slova č i ć te napiši još četiri riječi u kojima se pojavljuju.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Na 6 polica nalaze se po 8 knjiga. Čuvarica je posudila 9 knjiga. Koliko je knjiga ostalo? Pokaži množenje i oduzimanje.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga odredila na koju policu pripada svaka knjiga? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":18,"title":"Sat koji vraća minute","ribbon":"DAN 18 · DVORANA VREMENA","story":[{"heading":"Avantura 18 · Sat koji vraća minute","html":"<section class='story-scene single-story'><h3>Sat koji vraća minute</h3><p>U Dvorani vremena veliki je sat kasnio deset minuta. Zbog toga su se vrata otvarala prerano, a šumski stanovnici stalno su propuštali svoje susrete. Inga je usporedila mali sunčani sat s velikim satom, pomaknula kazaljke i provjerila vrijeme još jednom. Kad su oba sata pokazala isto, začulo se pravilno otkucavanje.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga provjerila je li veliki sat namješten točno?","options":["Usporedila ga je sa sunčanim satom.","Pogledala je kroz prozor.","Pitala je Milu."],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 18</small><h3>TIME</h3><p class='english-sentence'>What time is it?</p><button class='english-speak' data-english='What time is it?'>🔊 Poslušaj</button><p>Koliko je sati?</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „U Dvorani vremena veliki je sat kasnio deset minuta Zbog toga su se vrata otvarala prerano, a šumski stanovnici stalno su propuštali svoje susrete.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Upitne rečenice","text":"Od tvrdnje „Veliki sat kasni.” napiši dvije upitne rečenice. Na kraju svake stavi odgovarajući znak.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Susret je trebao početi u 10:30, a sat je kasnio 10 minuta. Što je pokazivao veliki sat? Ako je susret trajao 45 minuta, kada je završio? Napiši oba vremena.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga provjerila je li veliki sat namješten točno? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":19,"title":"Jezero koje pamti","ribbon":"DAN 19 · OGLEDALO VODE","story":[{"heading":"Avantura 19 · Jezero koje pamti","html":"<section class='story-scene single-story'><h3>Jezero koje pamti</h3><p>Na površini Jezera zrcala pojavljivale su se slike svega što su posjetitelji učinili toga dana. Inga je vidjela kako je putem podigla odbačeni papir i vratila ptiću grančicu za gnijezdo. Jezero je zasjalo zeleno. Mudra sova rekla je da mala dobra djela često nitko ne primijeti, ali ona ipak mijenjaju svijet.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Zašto je jezero zasjalo zeleno?","options":["Jer je počela kiša.","Jer je Inga učinila mala dobra djela.","Jer je sunce zašlo."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 19</small><h3>LAKE</h3><p class='english-sentence'>The lake is clean.</p><button class='english-speak' data-english='The lake is clean.'>🔊 Poslušaj</button><p>Jezero je čisto.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Na površini Jezera zrcala pojavljivale su se slike svega što su posjetitelji učinili toga dana Inga je vidjela kako je putem podigla odbačeni papir i vratila ptiću grančicu za gnijezdo.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Usklične rečenice","text":"Napiši dvije usklične rečenice koje bi Mudra sova mogla izgovoriti kada je jezero zasjalo. Pazi na uskličnik.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Uz jezero je bilo 28 papirnatih otpadaka. Inga je pokupila 12, a Bor još 9. Koliko ih je ostalo? Računaj korak po korak.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Zašto je jezero zasjalo zeleno? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":20,"title":"Tragovi u magli","ribbon":"DAN 20 · STAZA ZAKLJUČAKA","story":[{"heading":"Avantura 20 · Tragovi u magli","html":"<section class='story-scene single-story'><h3>Tragovi u magli</h3><p>Gusta magla prekrila je stazu. Na tlu su se vidjela tri različita traga: sitne ptičje nožice, široke medvjeđe šape i dugačak trag repa. Inga je morala pronaći trag koji vodi prema mostu. Prisjetila se da je Bor spomenuo mokar rep i odabrala dugačak trag. Magla se razmaknula čim je objasnila svoj zaključak.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koji je trag vodio prema Boru?","options":["Trag ptičjih nožica.","Trag širokih šapa.","Dugačak trag repa."],"answer":2},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 20</small><h3>FOG</h3><p class='english-sentence'>I can see the tracks.</p><button class='english-speak' data-english='I can see the tracks.'>🔊 Poslušaj</button><p>Vidim tragove.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Gusta magla prekrila je stazu Na tlu su se vidjela tri različita traga: sitne ptičje nožice, široke medvjeđe šape i dugačak trag repa.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Izjavne, upitne i usklične rečenice","text":"Iz priče napiši jednu izjavnu rečenicu. Zatim je pretvori u upitnu i uskličnu rečenicu.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Staza je duga 90 metara. Inga je prošla 35 metara, a zatim još 28 metara. Koliko joj je metara ostalo? Zbroji prijeđeno pa oduzmi od ukupne duljine.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koji je trag vodio prema Boru? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":21,"title":"Vrt riječi","ribbon":"DAN 21 · SJEMENKE PRIČE","story":[{"heading":"Avantura 21 · Vrt riječi","html":"<section class='story-scene single-story'><h3>Vrt riječi</h3><p>U Vrtu riječi svaka je biljka rasla iz jedne pažljivo odabrane riječi. Lijepe i točne riječi davale su snažne cvjetove, a nejasne riječi rasle su krivo. Inga je zamijenila riječ nešto riječju svjetlucavi cvijet i opis je odmah postao jasniji. Vrtlar joj je predao sjeme za završni dio puta.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Zašto je izraz „svjetlucavi cvijet” bio bolji od riječi „nešto”?","options":["Bio je kraći.","Bio je jasniji i precizniji.","Bio je glasniji."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 21</small><h3>FLOWER</h3><p class='english-sentence'>It is a bright flower.</p><button class='english-speak' data-english='It is a bright flower.'>🔊 Poslušaj</button><p>To je svijetli cvijet.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „U Vrtu riječi svaka je biljka rasla iz jedne pažljivo odabrane riječi Lijepe i točne riječi davale su snažne cvjetove, a nejasne riječi rasle su krivo.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Pridjevi","text":"U prepisanim rečenicama podcrtaj riječi koje opisuju kakvo je nešto. Napiši tri pridjeva kojima bi opisala Veliku šumu.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"U 5 gredica posađeno je po 7 sjemenki. Niknule su 23 biljke. Koliko sjemenki nije niknulo? Prvo izračunaj broj posađenih sjemenki.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Zašto je izraz „svjetlucavi cvijet” bio bolji od riječi „nešto”? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":22,"title":"Most od pitanja","ribbon":"DAN 22 · RIJEKA ZNATIŽELJE","story":[{"heading":"Avantura 22 · Most od pitanja","html":"<section class='story-scene single-story'><h3>Most od pitanja</h3><p>Pred Inge se spustio most sastavljen od pitanja. Svaka daska nosila je jedno: Tko? Što? Gdje? Kada? Zašto? Kako? Most se učvrstio tek kada je Inga uz svako pitanje pronašla smislen odgovor iz priče. Posljednja daska pitala je: Zašto je važno pitati? Inga je odgovorila da pitanja pomažu otkrivati ono što još ne znamo.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što se dogodilo kada je Inga pronašla smislene odgovore?","options":["Most se učvrstio.","Most je nestao.","Rijeka se osušila."],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 22</small><h3>QUESTION</h3><p class='english-sentence'>Why do we ask questions?</p><button class='english-speak' data-english='Why do we ask questions?'>🔊 Poslušaj</button><p>Zašto postavljamo pitanja?</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Pred Inge se spustio most sastavljen od pitanja Svaka daska nosila je jedno: Tko? Što? Gdje? Kada? Zašto? Kako? Most se učvrstio tek kada je Inga uz svako pitanje pronašla smislen odgovor iz priče.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Red riječi u rečenici","text":"Složi pravilne rečenice od skupina riječi: „pitanja / Inga / postavlja” i „most / učvrstio / se”. Zatim napiši vlastitu rečenicu.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Most ima 8 dijelova, a svaki dio 4 daske. Zamijenjeno je 11 dasaka. Koliko starih dasaka još ostaje? Izračunaj ukupan broj dasaka i oduzmi zamijenjene.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što se dogodilo kada je Inga pronašla smislene odgovore? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":23,"title":"Dvorana ogledala","ribbon":"DAN 23 · JEDNINA I MNOŽINA","story":[{"heading":"Avantura 23 · Dvorana ogledala","html":"<section class='story-scene single-story'><h3>Dvorana ogledala</h3><p>U Dvorani ogledala jedan se predmet pretvarao u mnogo jednakih predmeta. Jedan ključ postao je ključevi, jedna zvijezda zvijezde, a jedan list listovi. Inga je brzo primijetila da se riječi mijenjaju kada govorimo o više predmeta. Kad je pravilno imenovala sve skupine, ogledala su pokazala skrivena vrata.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je Inga primijetila o riječima u ogledalima?","options":["Riječi su nestajale.","Riječi su se mijenjale kada je predmeta bilo više.","Sve su riječi bile iste."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 23</small><h3>ONE AND MANY</h3><p class='english-sentence'>One star, many stars.</p><button class='english-speak' data-english='One star, many stars.'>🔊 Poslušaj</button><p>Jedna zvijezda, mnogo zvijezda.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „U Dvorani ogledala jedan se predmet pretvarao u mnogo jednakih predmeta Jedan ključ postao je ključevi, jedna zvijezda zvijezde, a jedan list listovi.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Jednina i množina","text":"Napiši množinu riječi ključ, zvijezda, list i knjiga. Zatim odaberi dvije riječi u množini i vrati ih u jedninu.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"U svakom od 6 ogledala vide se po 4 zvijezde. Tri su se zvijezde ugasile. Koliko ih još svijetli? Pokaži dva koraka.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je Inga primijetila o riječima u ogledalima? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":24,"title":"Poruka skrivena u kori","ribbon":"DAN 24 · SUPROTNOSTI","story":[{"heading":"Avantura 24 · Poruka skrivena u kori","html":"<section class='story-scene single-story'><h3>Poruka skrivena u kori</h3><p>Na kori Starog hrasta pojavila se poruka u kojoj su neke riječi bile izblijedjele. Pokraj svake je stajala riječ suprotnog značenja: svijetlo uz tamno, tiho uz glasno, blizu uz daleko. Inga je pomoću suprotnosti otkrila nedostajuće riječi. Poruka je glasila: Hrabrost nije odsutnost straha, nego odluka da nastaviš.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga otkrila nedostajuće riječi?","options":["Pomoću riječi suprotnog značenja.","Pomoću boje kore.","Pomoću brojeva."],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 24</small><h3>OPPOSITES</h3><p class='english-sentence'>Near and far.</p><button class='english-speak' data-english='Near and far.'>🔊 Poslušaj</button><p>Blizu i daleko.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Na kori Starog hrasta pojavila se poruka u kojoj su neke riječi bile izblijedjele Pokraj svake je stajala riječ suprotnog značenja: svijetlo uz tamno, tiho uz glasno, blizu uz daleko.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Riječi suprotnog značenja","text":"Napiši suprotnosti riječima svijetlo, tiho, blizu, brzo i hrabro. Jedan par upotrijebi u rečenici.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Hrast ima 100 urezanih znakova. Vidljiva su 64, a Inga je otkrila još 18. Koliko ih je još skriveno? Najprije zbroji vidljive znakove.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga otkrila nedostajuće riječi? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":25,"title":"Karta četiri smjera","ribbon":"DAN 25 · SJEVER, JUG, ISTOK, ZAPAD","story":[{"heading":"Avantura 25 · Karta četiri smjera","html":"<section class='story-scene single-story'><h3>Karta četiri smjera</h3><p>Mila je donijela novu kartu, ali na njoj nisu bili označeni smjerovi. Inga je stala tako da joj je jutarnje sunce bilo s desne strane. Zaključila je gdje je istok, zatim označila zapad, sjever i jug. Karta se ispunila tankim zlatnim crtama i pokazala put prema najvišem brežuljku.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga pronašla istok?","options":["Prema jutarnjem suncu.","Prema rijeci.","Prema zvuku sove."],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 25</small><h3>DIRECTIONS</h3><p class='english-sentence'>The sun rises in the east.</p><button class='english-speak' data-english='The sun rises in the east.'>🔊 Poslušaj</button><p>Sunce izlazi na istoku.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Mila je donijela novu kartu, ali na njoj nisu bili označeni smjerovi Inga je stala tako da joj je jutarnje sunce bilo s desne strane.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Pisanje naziva mjesta","text":"Napiši pravilno: velika šuma, rijeka znanja, jezero zrcala i stari hrast. Objasni zašto neke riječi pišemo velikim slovom.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Inga je išla 24 m prema istoku, 18 m prema sjeveru i 24 m prema zapadu. Koliko je ukupno metara prošla? Zbroji sve tri dionice.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga pronašla istok? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":26,"title":"Oluja iznad Akademije","ribbon":"DAN 26 · SIGURNA ODLUKA","story":[{"heading":"Avantura 26 · Oluja iznad Akademije","html":"<section class='story-scene single-story'><h3>Oluja iznad Akademije</h3><p>Iznad Akademije iznenada su se pojavili tamni oblaci. Vjetar je počeo savijati grane, a u daljini se začula grmljavina. Neki su stanovnici htjeli potrčati preko otvorene livade, ali Inga ih je zaustavila. Sklonili su se u čvrstu kuću i pričekali da oluja prođe. Mudra sova pohvalila je njezinu mirnu i sigurnu odluku.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Zašto Inga nije dopustila stanovnicima da potrče preko livade?","options":["Jer je livada bila mokra.","Jer je za vrijeme grmljavine sigurnije skloniti se u čvrstu kuću.","Jer su zaboravili kartu."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 26</small><h3>WEATHER</h3><p class='english-sentence'>The storm is over.</p><button class='english-speak' data-english='The storm is over.'>🔊 Poslušaj</button><p>Oluja je završila.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Iznad Akademije iznenada su se pojavili tamni oblaci Vjetar je počeo savijati grane, a u daljini se začula grmljavina.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Glagoli u prošlom vremenu","text":"Iz priče izdvoji pet glagola koji govore što se već dogodilo. Zatim napiši dvije rečenice o tome što je Inga učinila.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"U kući su bile 4 sobe s po 6 stanovnika. Još su stigla 3 stanovnika. Koliko ih je ukupno bilo u kući? Pokaži množenje i zbrajanje.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Zašto Inga nije dopustila stanovnicima da potrče preko livade? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":27,"title":"Sedmi ključ","ribbon":"DAN 27 · ČUVARICA ZNANJA","story":[{"heading":"Avantura 27 · Sedmi ključ","html":"<section class='story-scene single-story'><h3>Sedmi ključ</h3><p>Na vrhu brežuljka čekala je kamena kutija sa sedam udubljenja. Inga je u njih položila znakove koje je skupljala kroz cijelo putovanje: vjeru, pažnju, razmišljanje, ustrajnost, dobrotu, znatiželju i hrabrost. Kutija se otvorila, ali u njoj nije bio predmet. Sedmi ključ bio je spoznaja da se znanje povećava svaki put kada ga koristimo i dijelimo.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je zapravo bio sedmi ključ?","options":["Zlatni predmet.","Spoznaja da znanje raste kada ga koristimo i dijelimo.","Karta Velike šume."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 27</small><h3>KNOWLEDGE</h3><p class='english-sentence'>Knowledge grows when we share it.</p><button class='english-speak' data-english='Knowledge grows when we share it.'>🔊 Poslušaj</button><p>Znanje raste kada ga dijelimo.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Na vrhu brežuljka čekala je kamena kutija sa sedam udubljenja Inga je u njih položila znakove koje je skupljala kroz cijelo putovanje: vjeru, pažnju, razmišljanje, ustrajnost, dobrotu, znatiželju i hrabrost.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Sažetak priče","text":"U tri rečenice napiši najvažnije događaje ove avanture: početak, sredinu i završetak. Pazi da rečenice budu povezane.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Inga je skupila 7 znakova. Svaki vrijedi 8 bodova, a za otvaranje kutije trebalo je 50 bodova. Koliko je bodova imala više nego što je bilo potrebno? Izračunaj umnožak, zatim razliku.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je zapravo bio sedmi ključ? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":28,"title":"Svečanost pod Starim hrastom","ribbon":"DAN 28 · PRVI VELIKI KRUG","story":[{"heading":"Avantura 28 · Svečanost pod Starim hrastom","html":"<section class='story-scene single-story'><h3>Svečanost pod Starim hrastom</h3><p>Svi stanovnici Velike šume okupili su se pod Starim hrastom. Na njegovim granama zasjalo je dvadeset osam zlatnih žireva, po jedan za svaki dan u kojem je Inga čitala, razmišljala i pokušavala ponovno. Mudra sova uručila joj je znak Čuvarice znanja. Inga je znala da put nije završio; sada je bila spremna sama postavljati pitanja i tražiti nove odgovore.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što predstavlja svaki zlatni žir na Starom hrastu?","options":["Jedan dan truda i učenja.","Jednu knjigu.","Jednog stanovnika šume."],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>WISE OWL · DAY 28</small><h3>CELEBRATION</h3><p class='english-sentence'>I am proud of my work.</p><button class='english-speak' data-english='I am proud of my work.'>🔊 Poslušaj</button><p>Ponosna sam na svoj trud.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove rečenice iz avanture: „Svi stanovnici Velike šume okupili su se pod Starim hrastom Na njegovim granama zasjalo je dvadeset osam zlatnih žireva, po jedan za svaki dan u kojem je Inga čitala, razmišljala i pokušavala ponovno.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Završni jezični izazov","text":"Napiši četiri rečenice o svom putovanju: jednu izjavnu, jednu upitnu, jednu uskličnu i jednu rečenicu s riječju u množini.","paper":true},{"skill":"Matematika","title":"3. Zadatak povezan s pričom","text":"Na hrastu je 28 žireva. Na 4 grane raspoređeni su jednako. Koliko je žireva na svakoj grani? Ako na svaku granu dodamo još 2, koliko ih je ukupno? Pokaži dijeljenje, zatim zbrajanje.","paper":true},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što predstavlja svaki zlatni žir na Starom hrastu? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]}];

