function applyBuild17Content(){
  ingaDays.forEach((d,i)=>{
    const c=build17Content[i];
    if(!c)return;
    d.story[2]={heading:"English with Wise Owl",html:`<div class='english-card'><small>ENGLISH · DAY ${d.number}</small><h3>${c.enTitle}</h3><p class='english-sentence'>${c.enSentence}</p><button class='english-speak' data-english='${c.enSentence.replace(/'/g,"&apos;")}'>Poslušaj</button><p>${c.enPrompt}</p></div>`};
    const writing=d.tasks.find(t=>t.skill==="Pisanje");
    const reading=d.tasks.find(t=>t.skill==="Čitanje s razumijevanjem");
    d.tasks=[
      writing||{skill:"Pisanje",title:"1. Prepiši uredno",text:"Prepiši dvije rečenice iz priče.",paper:true},
      {skill:"Hrvatski jezik",title:`2. ${c.hrTitle}`,text:c.hrText,paper:true},
      {skill:"Matematika",title:`3. ${c.mathTitle}`,text:c.mathText,paper:true},
      reading||{skill:"Čitanje s razumijevanjem",title:"4. Odgovori punom rečenicom",text:"Odgovori na pitanje iz priče punom rečenicom.",paper:true}
    ];
  });
}
applyBuild17Content();

