function workbookMath(day){
  const tables=[2,3,4,5,6,7,8,9],a=tables[(day-1)%tables.length],b=tables[(day+2)%tables.length];
  const mult=Array.from({length:6},(_,i)=>{const x=2+((i+day)%8),y=i%2?a:b;return {label:`${x} × ${y}`,answer:x*y};});
  const div=Array.from({length:6},(_,i)=>{const y=i%2?a:b,x=2+((i+day+1)%8);return {label:`${x*y} ÷ ${y}`,answer:x};});
  return {mult,div};
}
