let forestAmbienceStop=null;
function startForestAmbience(){
  try{
    if(forestAmbienceStop)forestAmbienceStop();
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!AC)return ()=>{};
    const ctx=new AC();
    const master=ctx.createGain(); master.gain.value=.065; master.connect(ctx.destination);
    // Šum lišća i udaljeni noćni zvukovi
    const len=ctx.sampleRate*3,buf=ctx.createBuffer(1,len,ctx.sampleRate),data=buf.getChannelData(0);
    let last=0;
    for(let i=0;i<len;i++){const white=Math.random()*2-1;last=.985*last+.015*white;data[i]=last*.75+white*.13}
    const noise=ctx.createBufferSource();noise.buffer=buf;noise.loop=true;
    const filter=ctx.createBiquadFilter();filter.type='bandpass';filter.frequency.value=1250;filter.Q.value=.45;
    const noiseGain=ctx.createGain();noiseGain.gain.value=.42;noise.connect(filter).connect(noiseGain).connect(master);noise.start();
    // Blagi šapat vjetra
    const wind=ctx.createOscillator();wind.type='sine';wind.frequency.value=.13;
    const windGain=ctx.createGain();windGain.gain.value=.025;wind.connect(windGain.gain);windGain.connect(master);wind.start();
    const timers=[];
    const chirp=()=>{
      if(ctx.state==='closed')return;
      const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';
      const now=ctx.currentTime;o.frequency.setValueAtTime(1700+Math.random()*900,now);o.frequency.exponentialRampToValueAtTime(2300+Math.random()*1200,now+.12);
      g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(.12,now+.025);g.gain.exponentialRampToValueAtTime(.001,now+.22);
      o.connect(g).connect(master);o.start(now);o.stop(now+.24);
      timers.push(setTimeout(chirp,900+Math.random()*1900));
    };
    timers.push(setTimeout(chirp,550));
    forestAmbienceStop=()=>{timers.forEach(clearTimeout);try{noise.stop();wind.stop()}catch(e){};master.gain.cancelScheduledValues(ctx.currentTime);master.gain.setValueAtTime(master.gain.value,ctx.currentTime);master.gain.linearRampToValueAtTime(0,ctx.currentTime+.55);setTimeout(()=>ctx.close().catch(()=>{}),650);forestAmbienceStop=null};
    return forestAmbienceStop;
  }catch(e){console.warn('Forest ambience unavailable',e);return ()=>{}}
}
function typeDadSignature(element,text,onDone){
  element.textContent='';
  element.style.opacity='1';
  element.classList.add('is-writing');
  let i=0;
  const timer=setInterval(()=>{
    element.textContent=text.slice(0,++i);
    if(i>=text.length){clearInterval(timer);element.classList.remove('is-writing');onDone?.()}
  },88);
  return ()=>clearInterval(timer);
}


function startLivingOwl(overlay){
  const owl=overlay?.querySelector('.owl-character');
  if(!owl)return ()=>{};
  let stopped=false,blinkTimer=null,poseTimer=null,speechTimer=null;
  const clearPose=()=>owl.classList.remove('look-left','look-right','look-scroll','look-viewer','look-acorn','is-warm','is-listening');
  const scheduleBlink=()=>{
    if(stopped)return;
    blinkTimer=setTimeout(()=>{
      const doubleBlink=Math.random()<.22;
      owl.classList.add(doubleBlink?'is-double-blinking':'is-blinking');
      setTimeout(()=>owl.classList.remove('is-blinking','is-double-blinking'),doubleBlink?580:270);
      scheduleBlink();
    },3000+Math.random()*4000);
  };
  const schedulePose=()=>{
    if(stopped)return;
    poseTimer=setTimeout(()=>{
      if(!owl.classList.contains('is-speaking')){
        clearPose();
        const poses=['look-left','look-right','look-viewer'];
        owl.classList.add(poses[Math.floor(Math.random()*poses.length)],'is-listening');
        setTimeout(()=>{if(!stopped&&!owl.classList.contains('is-speaking')){clearPose();owl.classList.add('look-viewer')}},1000+Math.random()*850);
      }
      schedulePose();
    },2200+Math.random()*2600);
  };
  owl.classList.add('look-viewer','is-listening');
  scheduleBlink();schedulePose();
  return {
    look(mode){clearPose();owl.classList.add(mode)},
    speak(ms=4300){clearTimeout(speechTimer);clearPose();owl.classList.add('look-viewer','is-warm','is-speaking');speechTimer=setTimeout(()=>{owl.classList.remove('is-speaking');clearPose();owl.classList.add('look-viewer','is-listening')},ms)},
    warm(){owl.classList.add('is-warm')},
    stop(){stopped=true;clearTimeout(blinkTimer);clearTimeout(poseTimer);clearTimeout(speechTimer);owl.className='owl-character'}
  };
}

function showIngaCompletion(day,milestone){
  stopSpeech();
  const overlay=document.getElementById("ingaFinalParchment");
  if(!overlay)return;
  const isCinematic=day.number>=15&&day.number<=28;
  overlay.classList.toggle("cinematic-enabled",isCinematic);
  overlay.setAttribute("aria-label",`Završetak ${day.number}. avanture`);
  overlay.querySelector(".completion-summary").textContent=`Završila si Dan ${day.number} i osvojila Zlatni žir.`;
  overlay.querySelector(".completion-milestone").innerHTML=milestone||"";
  const signature=overlay.querySelector(".dad-message strong");
  signature.textContent="❤️ Voli te tata.";
  overlay.hidden=false;
  overlay.classList.remove("is-closing","is-visible","cinema-sequence-running","cinema-sequence-finale");
  void overlay.offsetWidth;
  requestAnimationFrame(()=>overlay.classList.add("is-visible"));

  const timers=[]; let stopForest=()=>{};
  const later=(fn,ms)=>timers.push(setTimeout(fn,ms));

  if(isCinematic){
    stopForest=startForestAmbience();

    // The visual ending is now an approved illustrated frame sequence, not a CSS-drawn scroll.
    const img=overlay.querySelector(".cinema-sequence-image");
    const card=overlay.querySelector(".inga-parchment-card");
    if(card) card.style.display="none";
    overlay.classList.add("cinema-sequence-running");

    const sequence=[
      [1,0],     // sova dolijeće s pergamentom
      [2,1500],  // ispušta ga
      [3,2700],  // pergament pada
      [4,3900],  // počinje se odmotavati
      [5,5200],  // potpuno otvoren
      [6,6500],  // poruka se pojavljuje
      [7,8000],  // rukopis "Voli te tata."
      [8,9400],  // potpis ostaje
      [9,10800]  // krijesnice + Vidimo se sutra
    ];
    sequence.forEach(([n,ms])=>later(()=>{
      if(img){
        img.classList.remove("frame-change");
        img.src=`assets/cinematic-ending-frame-${String(n).padStart(2,"0")}.jpg`;
        void img.offsetWidth;
        img.classList.add("frame-change");
      }
      if(n===6) speak("Bravo Inga. Netko je danas posebno ponosan na tebe.","hr-HR");
      if(n===9){ overlay.classList.add("cinema-sequence-finale"); later(()=>speak("Vidimo se sutra.","hr-HR"),350); }
    },ms));

    // Continue button appears only after the film has finished.
    later(()=>{
      if(card){
        card.style.display="block";
        card.classList.add("sequence-end-card");
        card.querySelector(".parchment-acorn")?.setAttribute("hidden","");
        card.querySelector(".parchment-kicker")?.setAttribute("hidden","");
        const h=card.querySelector("h2"); if(h) h.style.display="none";
        const s=card.querySelector(".completion-summary"); if(s) s.style.display="none";
        const m=card.querySelector(".completion-milestone"); if(m) m.style.display="none";
        const d=card.querySelector(".dad-message"); if(d) d.style.display="none";
      }
    },11900);
  }else{
    const card=overlay.querySelector(".inga-parchment-card");
    if(card) card.style.display="";
    later(()=>speak("Bravo Inga. Netko je danas posebno ponosan na tebe.","hr-HR"),500);
  }

  const close=()=>{
    timers.forEach(clearTimeout); stopForest();
    overlay.classList.add("is-closing");
    setTimeout(()=>{
      overlay.classList.remove("is-visible","is-closing","cinema-sequence-running","cinema-sequence-finale");
      overlay.hidden=true;
      const card=overlay.querySelector(".inga-parchment-card");
      if(card){
        card.style.display="";
        card.classList.remove("sequence-end-card");
        card.querySelector(".parchment-acorn")?.removeAttribute("hidden");
        card.querySelector(".parchment-kicker")?.removeAttribute("hidden");
        const h=card.querySelector("h2"); if(h) h.style.display="";
        const s=card.querySelector(".completion-summary"); if(s) s.style.display="";
        const m=card.querySelector(".completion-milestone"); if(m) m.style.display="";
        const d=card.querySelector(".dad-message"); if(d) d.style.display="";
      }
      openAcademy("inga");
    },650);
  };
  overlay.querySelector(".parchment-continue").onclick=close;
  overlay.onclick=event=>{if(event.target===overlay&&overlay.classList.contains("cinema-sequence-finale"))close()};
}
function rewardOverlay(title,text,icon,cb){const o=document.createElement("div");o.className="reward-overlay";o.innerHTML=`<div class="reward-card"><div class="big-acorn">${icon}</div><h2>${title}</h2><p>${text}</p><button class="primary">Nastavi</button></div>`;document.body.appendChild(o);o.querySelector("button").onclick=()=>{o.remove();cb()}}
function simple(t,i,x){document.getElementById("simpleTitle").textContent=t;document.getElementById("simpleHeading").textContent=t;document.getElementById("simpleIcon").textContent=i;document.getElementById("simpleText").textContent=x;showView("simpleView")}
function renderHomeDays(){const make=(days,p)=>days.map((d,i)=>`<button class="home-day-card" data-home-day="${p}:${i}"><b>${d.number}</b><img class="home-day-acorn" src="assets/acorn-3d.png" alt="Zlatni žir"><span>${d.title}</span></button>`).join("");const a=document.getElementById("homeIngaDays"),n=document.getElementById("homeNikoDays");if(a)a.innerHTML=make(ingaDays,"inga");if(n)n.innerHTML=make(nikoDays,"niko");document.querySelectorAll("[data-home-day]").forEach(b=>b.onclick=()=>{const [p,i]=b.dataset.homeDay.split(":");profile=p;p==="inga"?startIngaDay(+i):startNikoDay(+i)});document.querySelectorAll("[data-home-progress]").forEach(b=>b.onclick=()=>simple("Pregled napretka","🏆",`${b.dataset.homeProgress==="inga"?"Inga":"Niko"}: ${doneCount(b.dataset.homeProgress)}/${b.dataset.homeProgress==="inga"?ingaDays.length:nikoDays.length} završenih avantura.`))}
function openVoiceModal(){refreshVoices();document.getElementById("voiceModal").hidden=false;const v=autoVoice("hr-HR");document.getElementById("voiceHelp").textContent=v?`Trenutno odabrano: ${v.name}. Build 25 privremeno daje prednost muškom hrvatskom TTS glasu.`:"Na uređaju nije pronađen hrvatski ili srodni TTS glas. U postavkama uređaja instaliraj hrvatski govorni paket."}
function closeVoiceModal(){document.getElementById("voiceModal").hidden=true}

document.querySelectorAll("[data-profile]").forEach(b=>b.onclick=()=>openAcademy(b.dataset.profile));
document.querySelectorAll("[data-action]").forEach(b=>b.onclick=(event)=>{const a=b.dataset.action;if(a==="home"||a==="profiles")showView("homeView");if(a==="academy")openAcademy(profile||"inga");if(a==="speak")speak(profile==="inga"?`Odaberi pustolovinu od prvog do ${ingaDays.length}. dana.`:"Odaberi istraživački dan od prvog do četrnaestog dana.");if(a==="speak-inga-page"){
  const card=document.querySelector("#ingaPageContent .english-card");
  if(card){
    const keyword=card.querySelector("h3")?.innerText.trim()||"";
    const sentence=card.querySelector(".english-sentence")?.innerText.trim()||"";
    speak([keyword,sentence].filter(Boolean).join(". "),"en-GB");
  }else{
    speak(document.getElementById("ingaPageHeading").innerText+". "+document.getElementById("ingaPageContent").innerText,"hr-HR");
  }
}if(a==="pause-speech")pauseOrResumeSpeech();if(a==="stop-speech")stopSpeech();if(a==="inga-prev")turn(-1);if(a==="inga-next")turn(1);if(a==="font-up"){readingSize=Math.min(1.35,readingSize+.1);renderIngaPage()}if(a==="font-down"){readingSize=Math.max(.85,readingSize-.1);renderIngaPage()}if(a==="inga-story")showView("ingaDayView");if(a==="finish-inga-day"){event?.preventDefault?.();finishIngaDay();}if(a==="print-inga")window.print();if(a==="speak-niko"||a==="repeat-niko"){const s=nikoDays[nikoDayIndex].steps[nikoStep];speak(s.movement?nikoInstructionSpeech(s):s.speech)};if(a==="next-niko")nextNiko();if(a==="parent")simple("Roditeljski dio","👥",`Inga: ${doneCount("inga")}/${ingaDays.length} dana. Niko: ${doneCount("niko")}/${nikoDays.length} dana.`);if(a==="settings")openVoiceModal();if(a==="adventures")openAcademy(profile||"inga");if(a==="rewards")simple("Nagrade","🏆",`Ukupno osvojeno: ${doneCount("inga")+doneCount("niko")} nagrada.`);if(a==="progress")simple("Moj napredak","🎒",`Inga: ${doneCount("inga")}/${ingaDays.length} · Niko: ${doneCount("niko")}/${nikoDays.length}`);if(a==="messages")simple("Poruke Sveznalice","💌","Čitaj polako, razmisli, pokušaj i ne odustaj.")});
function addMagic(){document.querySelectorAll(".fireflies").forEach(l=>{if(l.children.length)return;for(let i=0;i<24;i++){const f=document.createElement("span");f.className="firefly";f.style.left=Math.random()*96+"%";f.style.top=Math.random()*85+"%";f.style.animationDelay=-Math.random()*6+"s";f.style.animationDuration=4+Math.random()*5+"s";l.appendChild(f)}})}
document.getElementById("finishIngaDayButton")?.addEventListener("click",event=>{event.preventDefault();finishIngaDay()});
document.getElementById("strategyReminder")?.addEventListener("click",flashStrategy);
document.getElementById("closeVoice")?.addEventListener("click",closeVoiceModal);document.getElementById("voiceModal")?.addEventListener("click",e=>{if(e.target.id==="voiceModal")closeVoiceModal()});document.getElementById("testVoice")?.addEventListener("click",()=>{const sel=document.getElementById("voiceSelect");if(sel?.value)selectedVoiceName=sel.value;speak("Bok, ja sam Mudra sova Sveznalica. Zajedno ćemo čitati, razmišljati i otkrivati tajne Velike šume.")});document.getElementById("saveVoice")?.addEventListener("click",()=>{const sel=document.getElementById("voiceSelect");if(sel?.value){selectedVoiceName=sel.value;localStorage.setItem("mudra.voice.name",selectedVoiceName)}updateVoiceStatus();closeVoiceModal()});
speechSynthesis.onvoiceschanged=refreshVoices;refreshVoices();renderHomeDays();addMagic();renderScore();if("serviceWorker" in navigator && location.protocol.startsWith("http")){navigator.serviceWorker.register("./sw.js").catch(()=>{});}


