function mk35day(){let m=(document.body.innerText||"").match(/DAN\s*(1[5-9]|2[0-8])\b/i);return m?+m[1]:null}
function showMudraKarta35(day=mk35day()){
 const x=MUDRA_KARTA_35[day]; if(!x)return;
 document.querySelector("#mk35")?.remove();

 const labels=[
   ["hr","Hrvatski",x[2]],
   ["mat","Matematika",x[3]],
   ["pid","Priroda i društvo",x[4]],
   ["eng","Engleski",x[5]],
   ["secret","Tajna dana",x[6]]
 ];

 let o=document.createElement("div");o.id="mk35";o.className=`mk353-overlay day${day}`;
 o.innerHTML=`
   <div class="mk353-bg"></div>
   <div class="mk353-fireflies">${Array.from({length:30},(_,i)=>`<i style="--i:${i}"></i>`).join("")}</div>

   <section class="mk353-stage" role="dialog" aria-modal="true">
     <button class="mk353-back" type="button" aria-label="Natrag"></button>
     <button class="mk353-exit" type="button">← Natrag na avanture</button>

     <div class="mk353-daycover">
       <small>DAN</small><strong>${day} / 28</strong><span>🌰 ${Math.max(0,day-1)}</span>
     </div>

     <button class="mk353-hot hr" data-index="0" aria-label="Hrvatski"></button>
     <button class="mk353-hot mat" data-index="1" aria-label="Matematika"></button>
     <button class="mk353-hot pid" data-index="2" aria-label="Priroda i društvo"></button>
     <button class="mk353-hot eng" data-index="3" aria-label="Engleski"></button>
     <button class="mk353-hot secret" data-index="4" aria-label="Tajna dana"></button>

     <button class="mk353-hot listen" aria-label="Poslušaj Mudru sovu"></button>
     <button class="mk353-hot save" aria-label="Spremi granu"></button>
     <button class="mk353-hot tree" aria-label="Moj Hrast znanja"></button>

     <div class="mk353-pop" hidden>
       <button class="mk353-popx" type="button">×</button>
       <div class="mk353-popicon"></div>
       <h3></h3>
       <p></p>
     </div>

     <div class="mk353-idea">
       <small>DANAS OTKRIVAM</small>
       <strong>${x[1]}</strong>
     </div>
   </section>`;
 document.body.appendChild(o);
 requestAnimationFrame(()=>o.classList.add("open"));

 const pop=o.querySelector(".mk353-pop");
 const showPop=(i)=>{
   const item=labels[i];
   pop.hidden=false;
   pop.querySelector(".mk353-popicon").textContent=i===0?"📖":i===1?"123":i===2?"🔎":i===3?"A":"🌰";
   pop.querySelector("h3").textContent=item[1];
   pop.querySelector("p").textContent=item[2];
   pop.classList.remove("show"); requestAnimationFrame(()=>pop.classList.add("show"));
   if(window.speakText) window.speakText(`${item[1]}. ${item[2]}.`);
 };
 o.querySelectorAll(".mk353-hot[data-index]").forEach(b=>b.onclick=()=>showPop(+b.dataset.index));
 o.querySelector(".mk353-popx").onclick=()=>{pop.hidden=true;pop.classList.remove("show")};
 const closeMudraKarta=()=>{
   try{ if("speechSynthesis" in window) speechSynthesis.cancel(); }catch(e){}
   o.classList.remove("open");
   setTimeout(()=>{
     o.remove();
     try{ openAcademy("inga"); }catch(e){}
   },220);
 };
 o.querySelector(".mk353-back").onclick=closeMudraKarta;
 o.querySelector(".mk353-exit").onclick=closeMudraKarta;

 o.querySelector(".mk353-hot.listen").onclick=()=>{
   const t=`Inga, pogledaj što si danas naučila. Tvoj Hrast znanja dobio je novu granu. Danas otkrivaš ${x[1].toLowerCase()}. ${x[6]}`;
   if(window.speakText) window.speakText(t);
   else if("speechSynthesis" in window){
     speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(t);u.lang="hr-HR";u.rate=.9;speechSynthesis.speak(u);
   }
 };
 o.querySelector(".mk353-hot.save").onclick=()=>{
   localStorage.setItem("ingaMudraKarta"+day,"1");
   o.classList.add("saved");
   pop.hidden=false;pop.querySelector(".mk353-popicon").textContent="🌳";
   pop.querySelector("h3").textContent="Nova grana je spremljena!";
   pop.querySelector("p").textContent="Tvoj Hrast znanja upravo je malo narastao.";
   requestAnimationFrame(()=>pop.classList.add("show"));
   setTimeout(()=>pop.hidden=true,2200);
 };
 o.querySelector(".mk353-hot.tree").onclick=()=>{
   o.classList.add("tree-focus");
   setTimeout(()=>o.classList.remove("tree-focus"),2200);
 };
}
document.addEventListener("DOMContentLoaded",()=>{
 let b=document.createElement("button");b.className="mk35fab";b.innerHTML="🌳 Mudra karta";b.onclick=()=>showMudraKarta35();document.body.appendChild(b);
 document.addEventListener("click",e=>{let q=e.target.closest("button");if(q&&/zavr(š|s)ila sam/i.test(q.innerText||"")){let d=mk35day();if(d>=15&&d<=28)setTimeout(()=>showMudraKarta35(d),12800)}},true)
});
